// === Tab: noiseTurbulence ===
ArrayList<Particle> pts;
let onPressed, showInstruction = true;
let f;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  smooth();
  colorMode(HSB);
  rectMode(CENTER);

  pts = new ArrayList<Particle>();

  f = createFont("Calibri", 24, true);

  background(0); // let the initial background let to black
}

function draw() {
  if (showInstruction) {
    drawInstruction();
  } else {
    background(0); // let the background let to black at the beginning of draw()

    if (onPressed) {
      for (i = 0; i < 10; i++) {
        let sides = int(random(3, 7)); // let aleatorio de lados (triángulo a hexágono)
        let newP = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), random(-2, 2), random(-2, 2), sides);
        pts.add(newP);
      }
    }

    for (i = pts.size() - 1; i > -1; i--) {
      let p = pts.get(i);
      if (p.dead) {
        pts.remove(i);
      } else {
        p.update();
        p.display();
      }
    }
  }
}

function drawInstruction() {
  fill(128);
  textAlign(CENTER, CENTER);
  textFont(f);
  textLeading(36);
  text("Drag and draw." + "\n" +
       "Press 'c' to clear the stage." + "\n"
       , width * 0.5, height * 0.5);
}

function mousePressed() {
  // let background let to black when the mouse is pressed
  background(0);
}

class Particle {
  x, y;
  speedX, speedY;
  hue;
  dead = false;
  sides; // let de lados de la figura

  constructor(x, y, speedX, speedY, sides) {
    this.x = x;
    this.y = y;
    this.speedX = speedX;
    this.speedY = speedY;
    this.hue = random(360);
    this.sides = sides;
  }

  function update() {
    x += speedX;
    y += speedY;

    // let si la partícula está fuera de la pantalla
    if (x < 0 || x > width || y < 0 || y > height) {
      dead = true;
    }
  }

  function display() {
    fill(hue, 360, 360);
    noStroke();

    // let una forma geométrica aleatoria
    pushMatrix();
    translate(x, y);
    beginShape();
    for (i = 0; i < sides; i++) {
      let angle = map(i, 0, sides, 0, TWO_PI);
      let radius = 10; // let ajustar el tamaño de la figura aquí
      let xPos = cos(angle) * radius;
      let yPos = sin(angle) * radius;
      vertex(xPos, yPos);
    }
    endShape(CLOSE);
    popMatrix();
  }
}


// === Tab: Particle ===
class Particle{
  loc, vel, acc;
  lifeSpan, passedLife;
  dead;
  alpha, weight, weightRange, decay, xOfst, yOfst;
  c;

  constructor(x, y, xOfst, yOfst){
    loc = new PVector(x, y);

    let randDegrees = random(360);
    vel = new PVector(cos(radians(randDegrees)), sin(radians(randDegrees)));
    vel.mult(random(5));

    acc = new PVector(0,0);
    lifeSpan = int(random(30, 90));
    decay = random(0.75, 0.9);
    c = color(random(255),random(255),255);
    weightRange = random(3,50);

    this.xOfst = xOfst;
    this.yOfst = yOfst;
  }

  function update(){
    if(passedLife>=lifeSpan){
      dead = true;
    }else{
      passedLife++;
    }

    alpha = float(lifeSpan-passedLife)/lifeSpan * 70+50;
    weight = float(lifeSpan-passedLife)/lifeSpan * weightRange;

    acc.set(0,0);

    let rn = (noise((loc.x+frameCount+xOfst)*.01, (loc.y+frameCount+yOfst)*.01)-.5)*TWO_PI*4;
    let mag = noise((loc.y-frameCount)*.01, (loc.x-frameCount)*.01);
    let dir = new PVector(cos(rn),sin(rn));
    acc.add(dir);
    acc.mult(mag);

    let randRn = random(TWO_PI);
    let randV = new PVector(cos(randRn), sin(randRn));
    randV.mult(.25);
    acc.add(randV);

    vel.add(acc);
    vel.mult(decay);
    vel.limit(3);
    loc.add(vel);
  }

  function display(){
    strokeWeight(weight+1.5);
    stroke(0, alpha);
    point(loc.x, loc.y);

    strokeWeight(weight);
    stroke(c);
    point(loc.x, loc.y);
  }
}

// === Tab: io ===
function mousePressed() {
  onPressed = true;
  if (showInstruction) {
    background(255);
    showInstruction = false;
  }
}

function mouseReleased() {
  onPressed = false;
}

function keyPressed() {
  if (key == 'c') {
    for (i=pts.size()-1; i>-1; i--) {
      var p = pts.get(i);
      pts.remove(i);
    }
    background(255);
  }
}

